                fadeGrid[y][x] = 0;
            }
        }
    };

    const clearGrid = () => {
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                grid[y][x] = null;
                fadeGrid[y][x] = 0;
            }
        }
    };

