            if (grid[y][x]) {
                grid[y][x] = null;
                fadeGrid[y][x] = 1;
            } else {
                grid[y][x] = { age: 0 };
                fadeGrid[y][x] = 0;
            }
        }
    });

    createUI();
    requestAnimationFrame(loop);
}

